#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using i128 = __int128_t;

const ll MOD = 998244353;
const ll MODD = 1000000007;
const int MAX_SIZE = 1000005;
const ll INF = 1000000000000000000LL;

ll powers[15];
vector<string> digit_lists[7];
vector<ll> sorted_differences[7][7];
ll prefix_sums[7][7];

inline ll string_to_number(const string& s) {
    ll result = 0;
    for (char c : s) {
        result = result * 10 + (c - '0');
    }
    return result;
}

inline i128 calculate(const string& prefix, int remaining, ll& counter) {
    if (remaining == -1) return 0;

    int left_size = remaining / 2;
    int right_size = remaining - left_size;
    if (remaining == 1) {
        left_size = 1;
        right_size = 0;
    }

    i128 total = (counter - string_to_number(prefix) + MOD * MOD) % MOD;
    counter++;

    for (const string& left : digit_lists[left_size]) {
        string combined = prefix + left;
        total += (-string_to_number(combined) + counter + MOD * MOD) % MOD;
        counter++;

        if ((int)left.size() == left_size) {
            ll value = string_to_number(combined) % MOD;
            for (int sz = 1; sz <= right_size; ++sz) {
                ll constant = (-value * powers[sz] + counter + MOD * MOD) % MOD;
                auto& vec = sorted_differences[right_size][sz];
                int pos = lower_bound(vec.begin(), vec.end(), MOD - constant) - vec.begin();
                total += (i128)vec.size() * constant + prefix_sums[right_size][sz] - (i128)MOD * (vec.size() - pos);
            }
            counter += digit_lists[right_size].size();
        }
    }
    return total;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n;
    cin >> n;
    string s = to_string(n);
    int N = s.length();

    powers[0] = 1;
    for (int i = 1; i <= 14; ++i) {
        powers[i] = powers[i-1] * 10;
    }

    for (int i = 0; i < MAX_SIZE; ++i) {
        string num_str = to_string(i);
        string padded = num_str;
        while ((int)padded.length() <= 6) {
            padded = "0" + padded;
            digit_lists[padded.length()].push_back(padded);
        }
    }

    for (int len = 1; len <= 6; ++len) {
        for (const string& prev : digit_lists[len-1]) {
            digit_lists[len].push_back(prev);
        }
        sort(digit_lists[len].begin(), digit_lists[len].end());

        for (int j = 0; j < (int)digit_lists[len].size(); ++j) {
            ll val = (j - stoi(digit_lists[len][j]) + MOD) % MOD;
            sorted_differences[len][digit_lists[len][j].length()].push_back(val);
        }

        for (int sz = 1; sz <= len; ++sz) {
            sort(sorted_differences[len][sz].begin(), sorted_differences[len][sz].end());
            for (ll v : sorted_differences[len][sz]) {
                prefix_sums[len][sz] += v;
            }
        }
    }

    vector<pair<string, int>> queries;
    string current = "";

    for (int i = 0; i < (int)s.length(); ++i) {
        for (int digit = 0; digit <= 9; ++digit) {
            if (digit == s[i] - '0') continue;
            if (i == 0 && digit == 0) continue;

            current += char('0' + digit);
            if (digit <= s[i] - '0') {
                queries.emplace_back(current, (int)s.length() - i - 1);
            } else {
                queries.emplace_back(current, (int)s.length() - i - 2);
            }
            current.pop_back();
        }
        current += s[i];
        queries.emplace_back(current, 0);
    }

    ll counter = 1;
    i128 answer = 0;
    sort(queries.begin(), queries.end());

    for (const auto& q : queries) {
        if (s[q.first.length() - 1] == q.first.back()) {
            answer += (-string_to_number(q.first) + counter + MOD * MOD) % MOD;
            counter++;
            continue;
        }
        answer += calculate(q.first, q.second, counter);
    }

    answer %= MODD;
    cout << (ll)answer << '\n';

    return 0;
}
